        {"name": "a", "type": "number"},
        {"name": "b", "type": "number"},
        {"name": "operation", "type": "string", "options": ["add", "subtract", "multiply", "divide"]}
      ],
      "response_status": 201,
      "response_fields": [
        {"name": "id", "type": "integer"},
        {"name": "a", "type": "number"},
        {"name": "b", "type": "number"},
        {"name": "operation", "type": "string", "options": ["add", "subtract", "multiply", "divide"]},
        {"name": "result", "type": "number"}
      ],
      "errors": [
        {"status": 400, "detail": "Division by zero"}
      ],
      "examples": [
        {
          "description": "adds two numbers",
          "status": 201,
          "request": {"a": 10, "b": 5, "operation": "add"},
          "response": {"a": 10, "b": 5, "operation": "add", "result": 15}
        },
        {
          "description": "subtracts two numbers",
          "status": 201,
          "request": {"a": 10, "b": 5, "operation": "subtract"},
          "response": {"a": 10, "b": 5, "operation": "subtract", "result": 5}
        },
        {
          "description": "multiplies two numbers",
          "status": 201,
          "request": {"a": 10, "b": 5, "operation": "multiply"},
          "response": {"a": 10, "b": 5, "operation": "multiply", "result": 50}
        },
        {
          "description": "divides two numbers",
          "status": 201,
          "request": {"a": 10, "b": 5, "operation": "divide"},
          "response": {"a": 10, "b": 5, "operation": "divide", "result": 2}
        },
        {
          "description": "rejects division by zero",
          "status": 400,
          "request": {"a": 10, "b": 0, "operation": "divide"},
          "response": {"detail": "Division by zero"}
        }
      ]
    },
    {
      "method": "GET",
      "path": "/api/calculations",
      "summary": "List all calculations, newest first",
      "request_fields": [],
      "response_status": 200,
      "response_fields": [
        {"name": "items", "type": "array", "description": "objects with id, a, b, operation, result"}
      ],
      "errors": [],
