        {
          "description": "lists calculations",
          "status": 200,
          "request": {},
          "response": {}
        }
      ]
    },
    {
      "method": "DELETE",
      "path": "/api/calculations",
      "summary": "Clear all calculations",
      "request_fields": [],
      "response_status": 200,
      "response_fields": [
        {"name": "cleared", "type": "boolean"}
      ],
      "errors": [],
      "examples": [
        {
          "description": "clears calculations",
          "status": 200,
          "request": {},
          "response": {"cleared": true}
        }
      ]
    }
  ],
  "tables": [
    {
      "name": "calculations",
      "columns": [
        {"name": "id", "type": "INTEGER", "constraints": "PRIMARY KEY AUTOINCREMENT"},
        {"name": "a", "type": "REAL", "constraints": "NOT NULL"},
        {"name": "b", "type": "REAL", "constraints": "NOT NULL"},
        {"name": "operation", "type": "TEXT", "constraints": "NOT NULL"},
        {"name": "result", "type": "REAL", "constraints": "NOT NULL"}
      ]
    }
  ],
  "db_functions": [
    {
      "name": "add_calculation",
      "signature": "add_calculation(a: float, b: float, operation: str) -> dict",
      "description": "Insert and return the new row"
    },
    {
      "name": "list_calculations",
      "signature": "list_calculations() -> list[dict]",
      "description": "All rows, newest first"
    },
    {
      "name": "clear_calculations",
      "signature": "clear_calculations() -> None",
      "description": "Clear all rows"
    }
  ],
  "ui_features": [
    "Form with two number inputs, an operation select (add, subtract, multiply, divide), and a Calculate button",
    "Display of the result",
    "History list of past calculations",
    "Clear history button",
    "Show error messages for division by zero"
  ]
}

